mapper.select:
SELECT  FROM reference_audio_assets
WHERE status='PUBLISHED' AND review_status != 'rejected' AND dataset_id=#{filter.datasetId}
AND category=#{filter.category}
AND technique=#{filter.technique}
AND register_name=#{filter.registerName}
AND yulmyeong=#{filter.yulmyeong}
AND pitch_id=#{filter.pitchId}
ORDER BY label_id,asset_id
